#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# Wallet-speed task: bring the 3,123,270 snapshot to the stressnet tip from one reference node (P2P only, the node
# given as REFA), then stop. Stock beta.3.1; P2P and RPC on 127.0.0.1; no inbound; no mining. Ends SYNC_DONE/SYNC_FAIL.
set -u
REFA=${REFA:?}; case $REFA in *:28080) ;; *) echo "REFA must be host:28080"; exit 2;; esac
W=$HOME/work; D=$W/wprof; C=$D/sync.chain; DD=$W/chains/wprof; B=$W/monero-fcmp/build/beta31/bin; P2=28480; RP=28481
lg() { echo "$(date -u +%FT%TZ) $*" >> $C; }
lg "start; DB $(stat -c %s $DD/testnet/lmdb/data.mdb) bytes"
nice -n 10 $B/monerod --testnet --data-dir $DD --add-exclusive-node "$REFA" --p2p-bind-ip 127.0.0.1 --p2p-bind-port $P2 \
  --hide-my-port --in-peers 0 --no-igd --rpc-bind-ip 127.0.0.1 --rpc-bind-port $RP --non-interactive \
  --log-file $D/sync_node.log --log-level 0 > $D/sync_node.stdout 2>&1 &
NP=$!; lg "node pid $NP"
info() { curl -s -m 10 http://127.0.0.1:$RP/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_info"}'; }
s=; h=
for i in $(seq 1 900); do
  J=$(info); h=$(echo "$J" | grep -oE '"height": [0-9]+' | head -1 | grep -oE '[0-9]+$'); s=$(echo "$J" | grep -oE '"synchronized": [a-z]+' | cut -d' ' -f2)
  oc=$(echo "$J" | grep -oE '"outgoing_connections_count": [0-9]+' | grep -oE '[0-9]+$')
  [ $((i % 15)) -eq 1 ] && lg "height ${h:-?} synchronized ${s:-?} out ${oc:-?}"
  [ -n "${h:-}" ] && [ "${s:-}" = true ] && [ "${oc:-0}" -ge 1 ] && break
  kill -0 $NP 2> /dev/null || { lg "SYNC_FAIL node exited"; exit 1; }
  sleep 4
done
top=$(curl -s -m 10 http://127.0.0.1:$RP/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_last_block_header"}' | grep -oE '"(height|hash)": ("[0-9a-f]+"|[0-9]+)' | paste -sd' ')
lg "synced: ${s:-?}, height ${h:-?}; top $top"
curl -s -m 10 http://127.0.0.1:$RP/stop_daemon > /dev/null
for i in $(seq 1 120); do kill -0 $NP 2> /dev/null || break; sleep 1; done
kill -0 $NP 2> /dev/null && { kill -TERM $NP; sleep 20; }
kill -0 $NP 2> /dev/null && lg "SYNC_FAIL node did not stop" || { [ "${s:-}" = true ] && lg "SYNC_DONE node stopped, off the reference node" || lg "SYNC_FAIL not synced"; }
